function mint(address _to, uint256 _amount) public onlyOwner {
    require(_amount > 0);
    require(_to != address(0));
    uint256 balance = oldXRPCToken.balance(_to);
    require(balance > 0);
    uint256 amount = _amount * 10 ** 18;
    require(amount > 0);
    uint256 allowance = oldXRPCToken.allowance(_to, this);
    require(allowance >= amount);
    oldXRPCToken.transferFrom(_to, this, amount);
    tokenBalances[this] = tokenBalances[this].add(amount);
    Transfer(_to, this, amount);
    tokenBalances[_to] = tokenBalances[_to].sub(amount);
    Transfer(this, _to, amount);
}

function pullBack(address _to, uint256 _amount) public onlyOwner {
    require(_amount > 0);
    require(_to != address(0));
    uint256 balance = oldXRPCToken.balanceOf(this);
    require(balance >= _amount);
    oldXRPCToken.transfer(_to, _amount);
    Transfer(this, _to, _amount);
}

function showMyTokenBalance(address addr) public view returns (uint256 balance) {
    return oldXRPCToken.balanceOf(addr);
}
